// Good code: Uses PreparedStatement to prevent SQL injection
import java.sql.*;

public class SecureExample {
    public static void main(String[] args) {
        String username = "admin"; // Simulated user input
        String password = "password123"; // Simulated user input

        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");

            // Secure: Using PreparedStatement with parameterized queries
            String query = "SELECT * FROM users WHERE username = ? AND password = ?";
            PreparedStatement pstmt = conn.prepareStatement(query);

            // Set parameters safely, preventing SQL injection
            pstmt.setString(1, username);
            pstmt.setString(2, password);

            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                System.out.println("User found: " + rs.getString("username"));
            } else {
                System.out.println("User not found");
            }

            rs.close();
            pstmt.close();
            conn.close();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
